<?php
namespace App\Http\Controllers;
use App\Models\{Attendance,Branch,ChartOfAccount,Currency,Employee,Payroll,PayrollItem,Transaction}; use App\Services\OperationalLedgerService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class PayrollController extends Controller {
 public function index(){return view('hr.payroll.index',['payrolls'=>Payroll::with(['branch','currency'])->latest('year')->latest('month')->paginate(20),'branches'=>Branch::all(),'currencies'=>Currency::where('is_active',1)->get()]);}
 public function generate(Request $r){$d=$r->validate(['month'=>'required|integer|between:1,12','year'=>'required|integer|min:2020','branch_id'=>'nullable|exists:branches,id','currency_id'=>'required|exists:currencies,id']);$payroll=Payroll::firstOrCreate(['month'=>$d['month'],'year'=>$d['year'],'branch_id'=>$d['branch_id']],$d+['created_by'=>auth()->id()]);$employees=Employee::where('is_active',1)->when($d['branch_id'],fn($q)=>$q->where('branch_id',$d['branch_id']))->get();$days=cal_days_in_month(CAL_GREGORIAN,$d['month'],$d['year']); foreach($employees as $e){$att=Attendance::where('employee_id',$e->id)->whereMonth('date',$d['month'])->whereYear('date',$d['year'])->get();$absent=$att->where('status','absent')->count();$present=$att->whereIn('status',['present','half_day'])->count();$basic=(float)$e->salary;$deduction=$days?($basic/$days)*$absent:0;$net=max(0,$basic-$deduction);PayrollItem::updateOrCreate(['payroll_id'=>$payroll->id,'employee_id'=>$e->id],['basic_salary'=>$basic,'allowances'=>0,'overtime'=>0,'deductions'=>$deduction,'tax'=>0,'net_salary'=>$net,'present_days'=>$present,'absent_days'=>$absent]);}$this->recalc($payroll);return redirect()->route('hr.payroll.show',$payroll)->with('success','Payroll generated.');}
 public function show(Payroll $payroll){$payroll->load('items.employee','branch','currency');return view('hr.payroll.show',compact('payroll'));}
 public function updateItem(Request $r,PayrollItem $item){$d=$r->validate(['allowances'=>'required|numeric|min:0','overtime'=>'required|numeric|min:0','deductions'=>'required|numeric|min:0','tax'=>'required|numeric|min:0']);$d['net_salary']=(float)$item->basic_salary+$d['allowances']+$d['overtime']-$d['deductions']-$d['tax'];$item->update($d);$this->recalc($item->payroll);return back()->with('success','Payroll item updated.');}
 public function post(Payroll $payroll,OperationalLedgerService $ledger){abort_unless($payroll->status==='draft',422);$currency=$payroll->currency_id;$rate=\App\Models\FxRate::where(['branch_id'=>$payroll->branch_id,'currency_id'=>$currency,'date'=>$payroll->payment_date?:now()->toDateString()])->value('close_rate')?:1;$amount=(float)$payroll->net_amount;$header=['date'=>$payroll->payment_date?:now()->toDateString(),'branch_id'=>$payroll->branch_id?:auth()->user()->branch_id,'currency_id'=>$currency,'exchange_rate_afn'=>$rate,'module_name'=>'payroll','module_id'=>$payroll->id,'created_by'=>auth()->id(),'description'=>'Payroll '.$payroll->month.'/'.$payroll->year];$ledger->post($header,[['chart_of_account_id'=>$ledger->coa('5000'),'amount'=>$amount,'amount_afn'=>$amount*$rate,'direction'=>'debit'],['chart_of_account_id'=>$ledger->coa('1000'),'amount'=>$amount,'amount_afn'=>$amount*$rate,'direction'=>'credit','is_safe'=>1]]);$payroll->update(['status'=>'posted','posted_by'=>auth()->id(),'posted_at'=>now(),'payment_date'=>$header['date']]);return back()->with('success','Payroll posted to expenses and journal.');}
 private function recalc(Payroll $p){$gross=$p->items()->sum(DB::raw('basic_salary+allowances+overtime'));$ded=$p->items()->sum(DB::raw('deductions+tax'));$p->update(['gross_amount'=>$gross,'deduction_amount'=>$ded,'net_amount'=>$gross-$ded]);}
}
